fn lower_opaque_impl_trait(
        &mut self,
        span: Span,
        origin: hir::OpaqueTyOrigin,
        opaque_ty_node_id: NodeId,
        bounds: &GenericBounds,
        fn_kind: Option<FnDeclKind>,
        itctx: ImplTraitContext,
    ) -> hir::TyKind<'hir> {
